"""
Model Library for managing URDF model collections.

Provides browsing, searching, and loading of URDF models from
local storage and remote repositories.
"""

from __future__ import annotations

from collections.abc import Iterator
from pathlib import Path
from typing import Any

from model_generation.converters.urdf_parser import ParsedModel, URDFParser
from model_generation.core.contracts import postcondition, precondition
from model_generation.library._model_loader import load_model
from model_generation.library._model_operations import (
    add_local_model,
    create_editable_copy,
    remove_model,
)
from model_generation.library._model_registry import (
    load_index,
    register_bundled_models,
)
from model_generation.library._model_repository import (
    KNOWN_REPOSITORIES,
    add_repository,
    refresh_repository,
)
from model_generation.library._model_search import (
    get_categories,
    get_model,
    get_tags,
    iter_entries,
    list_models,
)
from model_generation.library._model_types import (
    LibraryConfig,
    ModelCategory,
    ModelEntry,
    ModelFormat,
    RepositorySource,
)

__all__ = [
    "LibraryConfig",
    "ModelCategory",
    "ModelEntry",
    "ModelFormat",
    "ModelLibrary",
    "RepositorySource",
]


class ModelLibrary:
    """
    Comprehensive model library for URDF management.

    Features:
    - Local model indexing and storage
    - Remote repository integration (GitHub, etc.)
    - Model browsing and searching
    - Caching for offline access
    - Read-only library models vs. editable copies
    """

    KNOWN_REPOSITORIES = KNOWN_REPOSITORIES

    def __init__(self, config: LibraryConfig | None = None) -> None:
        """
        Initialize model library.

        Args:
            config: Library configuration
        """
        self.config = config or LibraryConfig()
        self._parser = URDFParser()
        self._entries: dict[str, ModelEntry] = {}
        self._repositories: dict[str, Any] = {}

        self.config.cache_dir.mkdir(parents=True, exist_ok=True)
        self.config.index_file.parent.mkdir(parents=True, exist_ok=True)

        load_index(self.config, self._entries)
        register_bundled_models(self._entries)

    def list_models(
        self,
        category: ModelCategory | None = None,
        source: RepositorySource | None = None,
        tags: list[str] | None = None,
        search: str | None = None,
    ) -> list[ModelEntry]:
        """
        List models matching criteria.

        Args:
            category: Filter by category
            source: Filter by source type
            tags: Filter by tags (any match)
            search: Search in name and description

        Returns:
            List of matching ModelEntry objects
        """
        return list_models(self._entries, category, source, tags, search)

    def get_model(self, model_id: str) -> ModelEntry | None:
        return get_model(self._entries, model_id)

    @precondition(
        lambda self, model_id, **kw: model_id is not None, "Model ID cannot be None"
    )
    @precondition(
        lambda self, model_id, **kw: len(model_id.strip()) > 0,
        "Model ID cannot be empty",
    )
    def load_model(
        self,
        model_id: str,
        force_download: bool = False,
    ) -> ParsedModel | None:
        """
        Load a model from the library (URDF or MJCF).

        Args:
            model_id: Model identifier
            force_download: Force re-download even if cached

        Returns:
            ParsedModel or None if not found
        """
        return load_model(
            self._entries, self._parser, self.config, model_id, force_download
        )

    @postcondition(lambda result: result is not None, "Must return a valid ModelEntry")
    @postcondition(lambda result: result.id, "ModelEntry must have an ID")
    def add_local_model(
        self,
        urdf_path: str | Path,
        name: str | None = None,
        category: ModelCategory = ModelCategory.OTHER,
        description: str = "",
        tags: list[str] | None = None,
        copy_to_library: bool = False,
    ) -> ModelEntry:
        """
        Add a local URDF model to the library.

        Args:
            urdf_path: Path to URDF file
            name: Display name (defaults to filename)
            category: Model category
            description: Model description
            tags: Tags for searching
            copy_to_library: If True, copy files to library storage

        Returns:
            Created ModelEntry
        """
        return add_local_model(
            self._entries,
            self._parser,
            self.config,
            urdf_path,
            name,
            category,
            description,
            tags,
            copy_to_library,
        )

    def add_repository(
        self,
        name: str,
        repo_type: str = "github",
        owner: str | None = None,
        repo: str | None = None,
        branch: str = "main",
        path: str | None = None,
        url: str | None = None,
    ) -> None:
        """
        Add a repository source.

        Args:
            name: Repository name for reference
            repo_type: Type (github, gitlab, url)
            owner: GitHub/GitLab owner
            repo: Repository name
            branch: Branch to use
            path: Subdirectory path
            url: Direct URL (for url type)
        """
        add_repository(
            self._repositories, name, repo_type, owner, repo, branch, path, url
        )

    def refresh_repository(self, repo_name: str) -> list[ModelEntry]:
        """
        Refresh models from a repository.

        Args:
            repo_name: Repository name

        Returns:
            List of discovered models
        """
        return refresh_repository(
            repo_name, self._repositories, self._entries, self.config
        )

    @precondition(
        lambda self, model_id, **kw: model_id is not None, "Model ID cannot be None"
    )
    @precondition(
        lambda self, model_id, **kw: len(model_id.strip()) > 0,
        "Model ID cannot be empty",
    )
    def create_editable_copy(
        self,
        model_id: str,
        new_name: str | None = None,
        destination: Path | None = None,
    ) -> ModelEntry | None:
        """
        Create an editable copy of a library model.

        Args:
            model_id: Source model ID
            new_name: Name for the copy
            destination: Destination directory

        Returns:
            New ModelEntry for the editable copy
        """
        return create_editable_copy(
            self._entries, self.config, model_id, new_name, destination
        )

    @precondition(
        lambda self, model_id, **kw: model_id is not None, "Model ID cannot be None"
    )
    def remove_model(self, model_id: str, delete_files: bool = False) -> bool:
        """
        Remove a model from the library.

        Args:
            model_id: Model to remove
            delete_files: If True, also delete cached files

        Returns:
            True if removed successfully
        """
        return remove_model(self._entries, self.config, model_id, delete_files)

    def get_categories(self) -> list[ModelCategory]:
        return get_categories(self._entries)

    def get_tags(self) -> list[str]:
        return get_tags(self._entries)

    def __iter__(self) -> Iterator[ModelEntry]:
        return iter_entries(self._entries)

    def __len__(self) -> int:
        return len(self._entries)

    def _download_model(self, entry: ModelEntry) -> Path:
        """Download a URL-sourced model into the cache.

        Validates the source URL scheme before downloading so that
        ``file://`` and other non-HTTPS schemes cannot be used to read
        local files or bypass network controls (SSRF prevention).
        See issue #4529.

        Args:
            entry: Model entry whose ``source_url`` should be downloaded.

        Returns:
            Path to the downloaded file in the cache directory.

        Raises:
            ValueError: If ``entry.source_url`` is missing or its scheme
                is not in the allowed set (``https`` only).
        """
        import urllib.request

        from src.shared.python.security.security_utils import validate_url_scheme

        if not entry.source_url:
            raise ValueError(f"ModelEntry {entry.id!r} has no source_url to download")

        # Allow only https. Tests in test_security_fixes.py assert that
        # file://, http://, ftp:// etc. raise before urlretrieve is called.
        validate_url_scheme(entry.source_url, allowed_schemes=("https",))

        cache_dir = self.config.cache_dir / entry.id
        cache_dir.mkdir(parents=True, exist_ok=True)
        dest = cache_dir / Path(entry.source_url).name

        urllib.request.urlretrieve(entry.source_url, dest)  # nosec B310 - scheme validated
        return dest
